INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_ROM_BELLONA_LIVY','ENT_ROM_BELLONA','SRC_LIVY_AUC','Livy, Ab Urbe Condita','Livy, Ab Urbe Condita','spear placed under his feet, to say these words: "Janus, Jupiter, father Mars, Quirinus, Bellona, ye Lares, ye gods Novensiles, ye gods Indigetes, ye divinities, under whose power we and our enemies are, and ye dii Manes, I pray you, I adore you, I ask your favour, that you would prosperously grant strength and victory to the Roman people, the Quirites; and that ye may affect the enemies of the Roman people, the Quirites, with terror, dismay, and death.','Canon Roberts',1912,'https://www.gutenberg.org/ebooks/19725',NULL,'primary-verbatim',NULL,true,'English translation (Canon Roberts, Everyman ed.) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ROM_JUPITER_LIVY','ENT_ROM_JUPITER','SRC_LIVY_AUC','Livy, Ab Urbe Condita','Livy, Ab Urbe Condita','The ambassador, when he comes to the frontiers of the people from whom satisfaction is demanded, having his head covered with a fillet, (the fillet is of wool,) says, "Hear, O Jupiter, hear, ye confines, (naming the nation they belong to,) let Justice hear.','Canon Roberts',1912,'https://www.gutenberg.org/ebooks/19725',NULL,'primary-verbatim',NULL,true,'English translation (Canon Roberts, Everyman ed.) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_ROM_MAGNA_MATER_LIVY','ENT_ROM_MAGNA_MATER','SRC_LIVY_AUC','Livy, Ab Urbe Condita','Livy, Ab Urbe Condita','Do you wish, according to the example of your ancestors, to augment the Roman state by admitting the vanquished among your citizens? Materials for extending your power by the highest glory are at hand. That government is certainly by far the most secure, which the subjects feel a pleasure in obeying. But whatever determination ye wish to come to, it is necessary that it be speedy.','Canon Roberts',1912,'https://www.gutenberg.org/ebooks/19725',NULL,'primary-verbatim',NULL,true,'English translation (Canon Roberts, Everyman ed.) located by name; verify book.chapter.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
